          "correct_answer": "B",
          "explanation": "SI = PRT/100 = 10000\u00d710\u00d72/100 = \u20b92000.\nCI = P[(1+R/100)^T - 1] = 10000[(1.1)\u00b2 - 1] = 10000[1.21-1] = 10000\u00d70.21 = \u20b92100.\nDifference = 2100 - 2000 = \u20b9100.\n\nShortcut for 2 years: Diff = P(R/100)\u00b2 = 10000(0.1)\u00b2 = \u20b9100."
