          "sample_high_scoring_response": "Social media companies have become some of the most prolific collectors of personal data in human history. Through user interactions, location tracking, browsing patterns, and third-party integrations, platforms like Facebook, Instagram, and Twitter accumulate vast datasets that fuel targeted advertising and algorithmic content curation. This data-driven business model generates billions in revenue but raises profound ethical questions.\n\nThe ethical implications are significant. Users often consent to data collection through lengthy, complex terms of service that few read or understand, raising questions about informed consent. Data breaches exposing millions of users\u2019 personal information have become alarmingly common. Furthermore, the use of personal data for political microtargeting and behavioral manipulation threatens democratic processes and individual autonomy.\n\nTo address these concerns, governments must enact comprehensive digital privacy legislation modeled on frameworks like the European Union\u2019s GDPR. Such laws should mandate transparent data collection practices, grant users genuine control over their data, and impose substantial penalties for violations. Simultaneously, technology companies should adopt privacy-by-design principles, embedding data protection into their products from inception rather than treating it as an afterthought.\n\nIn conclusion, while social media innovation should continue, it must be balanced with robust privacy protections that respect users\u2019 fundamental right to digital autonomy.",
