          "question": "Is ab > 0?\nStatement I: a + b > 0\nStatement II: a - b > 0",
          "options": {
            "A": "Statement I ALONE is sufficient.",
            "B": "Statement II ALONE is sufficient.",
            "C": "BOTH statements TOGETHER are sufficient.",
            "D": "NEITHER statement ALONE is sufficient, nor BOTH TOGETHER."
          },
          "correct_answer": "D",
          "explanation": "Let's check together. a+b>0 and a-b>0. Adding gives 2a>0 => a>0. If a=3, b=-1: a+b=2>0, a-b=4>0, ab=-3<0. If a=3, b=1: a+b=4>0, a-b=2>0, ab=3>0. Thus we cannot determine if ab>0. Neither statement together is sufficient. (Note: standard options sometimes have E as neither)."
